	private static List<Variant> variants(Family f) {
		String x = f.target();
		return List.of(
				new Variant("no ORDER BY", "SELECT ?s ?" + x, "", ""),
				new Variant("ORDER BY ?" + x, "SELECT ?s ?" + x, " ORDER BY ?" + x, x),
				new Variant("ORDER BY DESC LIMIT OFFSET", "SELECT ?s ?" + x,
						" ORDER BY DESC(?" + x + ") LIMIT 7 OFFSET 3", x),
				new Variant("ORDER BY ?" + x + " ?s", "SELECT ?s ?" + x, " ORDER BY ?" + x + " ?s", x + ",s"),
				new Variant("DISTINCT", "SELECT DISTINCT ?" + x, "", ""),
				new Variant("projection keeps ?v and ?" + x, "SELECT ?s ?v ?" + x, " ORDER BY ?" + x, x));
	}

	static Stream<Arguments> admitted() {
		List<Arguments> out = new ArrayList<>();
		for (Family f : FAMILIES) {
			for (Variant v : variants(f)) {
				out.add(Arguments.of(f.label() + " / " + v.suffix(), v.select() + " { " + f.body() + " }" + v.tail(),
						v.keys()));
			}
		}
		return out.stream();
	}

	static Stream<Arguments> families() {
		return FAMILIES.stream().map(f -> Arguments.of(f.label(), "SELECT ?s ?" + f.target() + " { " + f.body() + " }",
				f.target(), f.failsSomewhere()));
	}

